class SessionManagerServicer(auth_pb2_grpc.SessionServiceServicer):
    async def TerminateSession(self, request, context):
        caller = await get_session_caller(context)
        redis_client = get_redis_connection()
        raw_sess = await redis_client.get(f"sess:{request.session_id}")
        if not raw_sess:
            return auth_pb2.TerminateResponse(terminated=False)
        sess_data = json.loads(raw_sess)
        if sess_data.get("user_id") != caller.user_id:
            await context.abort(grpc.StatusCode.PERMISSION_DENIED, "Cannot terminate another user's session")
        deleted = await redis_client.delete(f"sess:{request.session_id}")
        return auth_pb2.TerminateResponse(terminated=bool(deleted))
